const flaw="[풀이] a ₁=2,a _(n +1)=a _n +3이다. ①a ₂=2 +3=5 ②a ₃=a ₁+3=5이다.";
lessons.push(concept({id:'A17',course:'algebra',unit:'sequence',title:"수열의 귀납적 정의와 초기 조건",standards:['12대수03-06'],prereqs:['A13','A14'],goals:["초기 값과 다음 항 규칙으로 항을 계산하고 귀납적 정의와 증명을 구별한다"],misconceptions:[{id:'A17-M1',claim:"다음 항을 구할 때 항상 첫째항에 규칙을 적용한다",repair:"방금 구한 현재 항을 다음 계산의 입력으로 넘긴다.",bridge:'B1'},{id:'A17-M2',claim:"점화 식만 있으면 초기 항 없이 수열 하나가 정해진다",repair:"같은 전이 규칙에도 다른 시작 값의 수열이 있다.",bridge:'B1'},{id:'A17-M3',claim:"다음 항 규칙이 있으면 과거 항도 항상 하나로 복원된다",repair:"규칙이 일 대 일이 아니면 거꾸로는 여러 후보일 수 있다.",bridge:'B1'}],prediction:"a _(n +1)=a _n +2라는 정보만으로 a ₃을 하나로 정할 수 있을까?",why:["수열을 모든 항의 일반 식으로 바로 주지 않고 시작 항과 다음 항을 만드는 규칙으로 정할 수 있다. 게임의 현재 상태에서 다음 상태로 옮기는 것처럼, 현재 값을 입력으로 받아 새 값을 계산한다. 시작 값이 없으면 같은 규칙을 따르는 여러 수열이 생기므로 초기 조건과 전이 규칙을 한 쌍으로 읽는다.","귀납적 정의는 대상을 만드는 방법이고 수학적 귀납법은 명제가 모든 항 번호에서 성립함을 보이는 증명 방법이다. 항을 몇 개 계산해 규칙을 관찰하는 것만으로 모든 항의 일반 식을 증명한 것은 아니다. 이 단원에서는 복잡한 일반항을 억지로 구하기보다 규칙을 정확히 실행하고, 필요한 이전 항 개수와 초기 정보를 파악하는 것을 중심에 둔다."],derivation:[{title:"시작 값",body:"a ₁=2처럼 첫 계산에 쓸 항을 정한다. 이전 두 항을 쓰는 규칙이면 초기 항도 보통 둘이 필요하다."},{title:"한 단계 적용",body:"a _(n +1)=2a _n +1이면 a ₂=5,a ₃=11이다. 새로 구한 a ₂를 다음 입력으로 쓴다."},{title:"정의와 검증",body:"몇 항을 보고 일반 식을 추측할 수는 있다. 그 식이 항상 맞는지는 시작 값과 전이 규칙을 모두 만족하는 이유를 별도로 확인해야 한다."}],formula:"$a_1=c,\\quad a_{n+1}=F(a_n)\\ (n\\ge1):\\ \\text{초기값과 전이 규칙을 함께 읽기}$",conditions:[{require:"규칙에 필요한 초기 항",ifMissing:"시작이 달라 다른 수열이 된다",example:"a _(n +1)=a _n +2에서 a ₁=1이면 1,3,5,…, a ₁=10이면 10,12,14,…다."},{require:"순 방향 계산과 역방향 유일성 구별",ifMissing:"정보를 잃는 전이를 거꾸로 하나로 복원한다",example:"a _(n +1)=a _n² 에서다음항 1의 이전 항은 1이나 −1일 수 있다."}],representation:{kind:'recurrence',controls:[control('a',"초기 항",1,4,1,2),control('r',"다음 항에 더할 수",-1,3,1,2),control('n',"항수",2,8,1,5)],task:"모델 a _(n +1)=a _n +d에서 시작 값과 규칙을 따로 바꿔 처음 몇 항을 표로 추적한다.",readBack:"차이가 같은 두 수열의 첫항이 다르면 뒤의 모든 항도 같을까?",caption:"이 조절기는 덧셈 점화 식 모델이며 모든 종류의 점화 식을 입력하는 계산기는 아니다."},example:{prompt:"a ₁=2,a _(n +1)=2a _n +1에서 a ₃은?",steps:[{title:"시작",body:"첫항 2를 현재 값으로 둔다."},{title:"한 번",body:"a ₂=2·2 +1=5다."},{title:"다시",body:"현재 항을 5로 바꿔 a ₃=2·5 +1=11을 얻는다."}],answer:'11'},faded:numberQ('faded',"a ₁=3,a _(n +1)=2a _n이다. a ₂=6이다. a ₃은?",12,"다음 입력은 6이므로 12다.","방금 구한 값을 쓴다.",6,"초기 값을 다시 썼다."),entry:[numberQ('entry',"함수 F(x)=2x +1에서 F(3)은?",7,"6 +1=7이다.","현재 입력을 대입한다."),numberQ('entry',"첫째항에서 제3 항까지 전이 횟수는?",2,"1 →2 →3으로 두 번이다.","항 번호와 이동 횟수를 구별한다.")],checks:[numberQ('basic',"a ₁=1,a _(n +1)=a _n +3일 때 a ₄는?",10,"1 →4 →7 →10이다.","새 항을 계속 다음 입력으로 쓴다.",4,"한 번만 전이했다."),numberQ('basic',"a ₁=2,a _(n +1)=2a _n +1일 때 a ₃은?",11,"2 →5 →11이다.","두 번 적용한다.",5,"초기 항에 한 번만 적용했다."),pickQ('transfer',"전이 규칙 a _(n +1)=a _n +2만 있다. 수열에 대한 판단은?", ["시작 항이 없어 수열 하나로 정해지지 않는다","공차가 2이므로 무조건 2,4,6,…다","처음 세 항을 모두 알아도 뒤는 계산 못 한다"],["예를 들어 시 작 1 과 시작 10이 모두 규칙에 맞는다.","초기 값 2를 근거 없이 정했다.","초기 항이 주어지면 순 방향 규칙으로 이어 갈 수 있다."],"서로 다른 시작 값 두 개를 넣는다.",['M2','M1']),numberQ('transfer',"b _n=a _n +1로 정의한다. a _(n +1)=2a _n +1이면 b _(n +1)=k·b _n이다. 계수 k는?",2,"b _(n +1)=a _(n +1)+1=2a _n +2=2b _n이다.","새 변수의 정의를 다음 항에도 적용한다.",1,"a의 전이 식의 상수와 b의 배율을 혼동했다."),...errorSet(flaw,['②','①',"오류 없음"],["a ₃은 현재 항 a ₂에 3을 더 해야 한다.","a ₂=5는 맞다.","두 번째 전이에 초기 값을 다시 썼다."],["다음 항 규칙의 입력은 바로 전 항이기 때문이다","점화 식은 항상 모든 항을 같게 만들기 때문이다","첫항 정보가 필요 없기 때문이다"],["현재 항을 갱신하며 계산한다.","덧셈 3 규칙이면 항마다 3 늘어난다.","시작 항이 있어야 계산을 시작한다."],numberQ('repair',"올바른 a ₃은?",8,"a ₂=5에서 3을 더해 8이다.","현재 항 5 를 쓴다.",5,"현재 값을 갱신하지 않았다."),"입력 화살표를 1 →2 →3으로 그린다."),pickQ('explanation',"“a _(n +1)=a _n² 이면 다음 항만 알아도 이 전실 수 항을 항상 하나로 안다.”의 판정은?", ["결함 있음: 제곱에서 부호 정보가 사라질 수 있다","옳음: 모든 규칙은 역 함수를 갖는다","결함 있음: 제곱으로는 다음 항도 계산 못 한다"],["1 과 −1은 모두 다음 항 1 을 만든다.","일 대 일 여부를 확인해야 한다.","현재 항을 알면 제곱해 다음 항은 정해진다."],"순 방향과 역방향을 나눠 본다.",['M3','M3'])],explanation:{prompt:"초기 조건· 규칙· 계산· 증명의 차이를 설명하자.",claims:["초기 항 필요","현재 항을 갱신","몇 사례는 일반 증명이 아님"],model:"초기 항과 전이 규칙으로 수열을 정의하고 계속 계산한다. 몇 항의 패턴은 추측을 돕지만 그 일반 식이 모든 항에서 맞는지 증명하는 일은 별도다."}}));
